    {
      "criterion": "The `default_model_uuid` validation error message is `\"The default_model_uuid does not exist in the model registry.\"` — no UUID value in the message.",
      "met": true
    },
    {
      "criterion": "The error shape `{ code, message }` is preserved for all 5 error messages — no structural breaking change.",
      "met": true
    },
    {
      "criterion": "All existing tests in `api-models.test.ts` pass (with updated assertions where needed).",
      "met": true
    }
  ],
